const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const action = (body.action || 'list_events').toLowerCase();
const allowed = ['list_events','add_event','get_today'];
if (!allowed.includes(action)) {
  throw new Error('Invalid action. Must be one of: ' + allowed.join(', '));
}
const subject   = body.subject   || '';
const startTime = body.startTime || body.start_time || '';
const endTime   = body.endTime   || body.end_time   || '';
const bodyText  = body.body      || '';
const days      = Number(body.days) || 7;
const confirmed = body.confirmed === true || body.confirmed === 'true';
return [{ json: { action, subject, startTime, endTime, bodyText, days, confirmed } }];

const raw = $input.first()?.json?.stdout ?? '';
let validation;
try { validation = JSON.parse(raw); } catch { validation = { allowed: true }; }
if (validation.allowed === false) {
  throw new Error('Safety validation blocked calendar operation: ' + (validation.reason || 'policy'));
}
const params = $('Parse Parameters').first().json;
return [{ json: params }];

const raw = $input.first()?.json?.stdout ?? $input.first()?.json?.stderr ?? '';
let result;
try { result = JSON.parse(raw); } catch { result = { success: false, error: raw || 'No output from CalendarOps.ps1' }; }
return [{ json: result }];
